'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Identity, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './identity.css'

import { IDENTITY_GLYPH, IDENTITY_GLYPHS, type IdentityGlyphName } from './glyphs'

/**
 * Identity: one player, rendered.
 *
 * An avatar, a name, and whatever the host puts beside them. `player-card`,
 * `leaderboard`, `podium`, `versus`, `presence` and `profile` all render a
 * player through this one component, so the avatar cases, the signed-out case
 * and the accessible name are decided once rather than six times.
 *
 * **It renders identity. It never performs authentication.** It makes no
 * network call, reads no cookie, writes no token and talks to no identity
 * provider. The host passes a player or passes null. `data-gs-anonymous` is the
 * host's word that there is no player, never a check this component made, and
 * never a security boundary: a host that hides content behind it has built
 * client-side access control, which this is not.
 *
 * The adapter's `player` is null before sign-in, so signed out is a first-class
 * state with its own rendering and its own test, not a fallback.
 *
 * A player with no picture gets a symbol: specimen 3a hashes the player's id to
 * one of eight hues and one of six glyphs, and says in words "never a face or
 * initial". So the fallback is deterministic, the same player is the same mark
 * on every surface, and nothing about it can be mistaken for a photograph.
 *
 * A player-supplied name is untrusted text. It is rendered as text and never as
 * HTML, and it wraps rather than escaping its row.
 */

/**
 * The shape of `GamestageAdapter.player`, restated here so the component can be
 * installed on its own. A host with a richer player passes the three fields.
 */
export interface IdentityPlayer {
  /** Stable id. Rides `data-gs-player`, so a test can find one row. */
  id: string
  /** What the player calls themselves. Untrusted text. */
  displayName?: string
  /** Where their picture is. The host's URL; this never fetches it itself. */
  avatarUrl?: string
}

export type IdentityPresence = 'online' | 'away' | 'offline'

export type IdentitySize = 'small' | 'default' | 'large'

/** Which of the three avatar cases rendered. See `data-gs-avatar`. */
export type IdentityAvatarCase = 'image' | 'fallback' | 'none'

/** Inline, the default, or the boxed row specimen 3a draws. */
export type IdentityPresentation = 'inline' | 'row'

export type IdentitySide = 'player' | 'opponent'

export interface IdentityProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Who this is. `null` is the signed-out case and renders as one; it is not an
   * error and it is not an empty render.
   */
  player: IdentityPlayer | null
  /** This is the player holding the device. Carries the word "you" in the name. */
  you?: boolean
  /** Whether that player is here now. The host knows; this never asks. */
  presence?: IdentityPresence
  /** Which step of the size scale the avatar and the name render at. */
  size?: IdentitySize
  /**
   * Whether to render an avatar at all. `false` gives `data-gs-avatar="none"`,
   * which is a supported rendering rather than a degraded one: a dense
   * leaderboard row is a legitimate place to want the name alone.
   */
  avatar?: boolean
  /**
   * `row` is the boxed line from specimen 3a: avatar, name, a line of small
   * print with the presence word and the host's detail, ringed in the side's
   * colour and standing on a shelf. The default is the bare inline pair.
   */
  presentation?: IdentityPresentation
  /**
   * Which side of a contest this player is on. Colours the row's ring. `you`
   * implies `player`; an opponent has to be said.
   */
  side?: IdentitySide
  /**
   * The name to show, when the host has a better one than `displayName`. Also
   * the way to localise the two defaults below.
   */
  label?: string
  /** Anything the host wants beside the name: a stat, a badge, a control. */
  children?: React.ReactNode
}

/**
 * The words that go with the states, fixed by the attribute contract so that
 * identity, player-card, leaderboard, podium, versus, presence and profile
 * cannot ship seven vocabularies for the same three states.
 */
const STATE_WORD = {
  you: 'you',
  anonymous: 'signed out',
} as const

/** Shown when there is no player, and when a player has no name of their own. */
const DEFAULT_LABEL = { anonymous: 'Guest', unnamed: 'Player' } as const

/** Eight hues, so identity.css can name a class per hue. */
export const IDENTITY_HUES = 8

/**
 * FNV-1a over the id. Not for security: for spreading ids evenly over 48
 * symbol-and-hue pairs, and for giving the same id the same pair on every
 * device and every render. `Math.imul` keeps it in 32 bits.
 */
function hash(text: string): number {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return h >>> 0
}

/** The symbol and the hue a player id lands on. Exported so a host can match them elsewhere. */
export function symbolFor(id: string): { glyph: IdentityGlyphName; hue: number } {
  const h = hash(id)
  return {
    // The modulo keeps the index inside the array; the assertion says so to
    // a compiler that cannot see it.
    glyph: IDENTITY_GLYPHS[h % IDENTITY_GLYPHS.length]!,
    hue: Math.floor(h / IDENTITY_GLYPHS.length) % IDENTITY_HUES,
  }
}

export function Identity({
  player,
  you = false,
  presence,
  size = 'default',
  avatar = true,
  presentation = 'inline',
  side,
  label,
  className,
  children,
  ...rest
}: IdentityProps) {
  // A URL that 404s must not leave a hole where a face was, so a failed image
  // falls back to the symbol. The failed URL is remembered rather than a
  // boolean, so the next player's picture is attempted rather than inheriting
  // the last one's failure.
  const [failedSrc, setFailedSrc] = React.useState<string | null>(null)

  const anonymous = player === null
  const src = player?.avatarUrl
  const hasImage = avatar && src !== undefined && src !== '' && src !== failedSrc

  const name =
    label ??
    player?.displayName?.trim() ??
    (anonymous ? DEFAULT_LABEL.anonymous : DEFAULT_LABEL.unnamed)
  const shown = name === '' ? DEFAULT_LABEL.unnamed : name

  const avatarCase: IdentityAvatarCase = !avatar ? 'none' : hasImage ? 'image' : 'fallback'

  // Signed out has no id to hash, so every guest shares one symbol. That is
  // right: they are not distinct players, and a symbol that changed per render
  // would read as a different person each time.
  const symbol = symbolFor(player?.id ?? '')
  const Glyph = IDENTITY_GLYPH[symbol.glyph]

  const row = presentation === 'row'
  const resolvedSide: IdentitySide | undefined = side ?? (you ? 'player' : undefined)

  // The name carries the state, because a screen reader user gets no dot, no
  // colour and no picture. Order matters: who it is, then what is true about
  // them. `data-gs-avatar="none"` adds nothing, deliberately: the player's name
  // is the name, and "no avatar" is not a fact about the player.
  const words = [shown]
  if (you) words.push(STATE_WORD.you)
  if (anonymous) words.push(STATE_WORD.anonymous)
  if (presence) words.push(presence)

  // Emphasis, not motion: the dot changes colour and does not move, so its
  // transition survives reduced motion, which is how a player who cannot see
  // motion still sees someone arrive. In the row it is a word with a dot
  // beside it; elsewhere it is the dot alone on the avatar's corner.
  const presenceMark =
    presence === undefined ? null : (
      <span
        className="gs-identity__presence"
        data-gs-scope="identity" data-gs-part="presence"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        <i className="gs-identity__presence-dot" />
        {row ? <span className="gs-identity__presence-word">{presence}</span> : null}
      </span>
    )

  const hasDetail = children !== undefined && children !== null
  const detail =
    (row && presence !== undefined) || hasDetail ? (
      // Host content stays announced. It is not part of the group's label, so
      // hiding it would silently drop whatever the host put here.
      <span className="gs-identity__detail" data-gs-scope="identity" data-gs-part="detail">
        {row ? presenceMark : null}
        {hasDetail ? <span className="gs-identity__detail-text">{children}</span> : null}
      </span>
    ) : null

  return (
    <div
      {...rest}
      className={['gs-identity', className].filter(Boolean).join(' ')}
      data-gs-component="identity"
      data-gs-player={player?.id}
      data-gs-anonymous={anonymous ? 'true' : undefined}
      data-gs-you={you ? 'true' : undefined}
      data-gs-presence={presence}
      data-gs-avatar={avatarCase}
      data-gs-size={size}
      data-gs-presentation={row ? 'row' : undefined}
      data-gs-side={resolvedSide}
      role="group"
      aria-label={words.join(', ')}
    >
      {/* The avatar is decorative: the name is beside it and the group's label
          above already says who this is, so announcing the picture as well
          would read the same player twice. Hence both an empty alt and
          aria-hidden, and the same treatment on the name and the dot. */}
      {avatarCase === 'none' ? null : (
        <span
          className={[
            'gs-identity__avatar',
            avatarCase === 'fallback' ? `gs-identity__avatar--hue-${symbol.hue}` : '',
          ]
            .filter(Boolean)
            .join(' ')}
          data-gs-scope="identity" data-gs-part="avatar"
          aria-hidden="true"
        >
          {avatarCase === 'image' ? (
            <img
              className="gs-identity__image"
              src={src}
              alt=""
              onError={() => setFailedSrc(src ?? null)}
            />
          ) : (
            <span className={`gs-identity__symbol gs-identity__symbol--${symbol.glyph}`}>
              <Glyph />
            </span>
          )}
          {row ? null : presenceMark}
        </span>
      )}
      <span className="gs-identity__text">
        {/* React escapes this. A name is the player's own text and never HTML;
            nothing here reaches dangerouslySetInnerHTML, by construction. */}
        <span className="gs-identity__name" data-gs-scope="identity" data-gs-part="label" aria-hidden="true">
          {shown}
        </span>
        {detail}
      </span>
      {/* No avatar to sit on, and not a row: the dot stands after the name. */}
      {!row && avatarCase === 'none' ? presenceMark : null}
    </div>
  )
}

/* Identity. Every value comes from a token; nothing here is a literal colour.

   Specimen 3a draws this and design/twins/3a.json measures ours against it:
   the avatar at three sizes ringed at the UI stroke with the presence dot on
   its corner, the no-picture symbol on a hued disc, and the boxed player and
   opponent row. */

.gs-identity {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-3);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* -- avatar ---------------------------------------------------------------- */
/* The shape is the theme's, not this file's: arcade sets --gs-shape-identity to
   `circle`, and a border-radius written here would be the one thing a theme
   swap could not reach. The default is the same rounded rectangle every other
   surface uses, so a theme that says nothing still looks like the system.

   The ring is the UI stroke, which arcade draws at 3px and the drawing draws
   at 3px on every avatar it has. */
.gs-identity__avatar {
  position: relative;
  flex: 0 0 auto;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-object);
  block-size: var(--gs-size-icon-object);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  user-select: none;
}

/* A style query rather than a value substitution, because the token is a shape
   word and not a length: `border-radius: circle` is invalid and would compute
   to a square corner, silently. */
@container style(--gs-shape-identity: circle) {
  .gs-identity__avatar { border-radius: var(--gs-radius-full); }
}

/* The picture clips itself to the shape, because the avatar cannot clip: the
   presence dot hangs off its corner. */
.gs-identity__image {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  border-radius: inherit;
}

/* -- the symbol, for a player with no picture ------------------------------ */
/* Eight hues from the id. The drawing paints eight of its own; the library has
   no hue tokens (a token request on the twin pair), so the eight colours that
   already carry a hue stand in, solid variants because a disc is a colour. */
.gs-identity__avatar--hue-0 { background: var(--gs-color-player-solid); }
.gs-identity__avatar--hue-1 { background: var(--gs-color-opponent-solid); }
.gs-identity__avatar--hue-2 { background: var(--gs-color-positive-solid); }
.gs-identity__avatar--hue-3 { background: var(--gs-color-warning-solid); }
.gs-identity__avatar--hue-4 { background: var(--gs-color-negative-solid); }
.gs-identity__avatar--hue-5 { background: var(--gs-color-reward-solid); }
.gs-identity__avatar--hue-6 { background: var(--gs-color-interactive-solid); }
.gs-identity__avatar--hue-7 { background: var(--gs-color-edge-high-solid); }

/* The mark is drawn in the edge colour, the same dark as the ring, at the
   control icon size on a default disc. Two of the six are filled with a colour
   of their own in the drawing, and the fill comes from the token here so the
   glyph itself stays colourless. */
.gs-identity__symbol {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--gs-size-icon-control);
  color: var(--gs-color-edge);
  line-height: 1;
}

.gs-identity__symbol .gs-glyph { stroke-width: var(--gs-stroke-glyph-small); }
.gs-identity__symbol--diamond .gs-glyph { fill: var(--gs-color-player-solid); }
.gs-identity__symbol--dot .gs-glyph { fill: var(--gs-color-warning-solid); }
.gs-identity__symbol--triangle .gs-glyph,
.gs-identity__symbol--bars .gs-glyph { fill: currentColor; }

/* -- name ------------------------------------------------------------------ */
.gs-identity__text {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  flex: 1 1 auto;
  min-inline-size: 0;
}

/* A name is the player's own text, so it is arbitrarily long and may have no
   spaces in it at all. It wraps rather than pushing the presence dot, the rank
   or the score out of the row. */
.gs-identity__name {
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;
}

.gs-identity__detail {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  /* The small print under the name: caption size, secondary ink. It inherited
     the page's body size, so in a leaderboard row "Away end" at 17px sat under
     "Niamh" at 12px and the row read upside down. */
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  line-height: 1.3;
  color: var(--gs-color-ink-secondary);
}

/* The drawing's sizes are 32, 48 and 64. The scale has 48 and 64; the small
   step takes control.small (40) until a 32px size token exists, which is a
   token request on the twin pair. */
.gs-identity[data-gs-size='small'] .gs-identity__avatar {
  inline-size: var(--gs-size-control-small);
  block-size: var(--gs-size-control-small);
}

.gs-identity[data-gs-size='small'] .gs-identity__symbol {
  font-size: var(--gs-size-icon-utility);
}

.gs-identity[data-gs-size='small'] .gs-identity__name {
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
}

.gs-identity[data-gs-size='large'] .gs-identity__avatar {
  inline-size: var(--gs-size-icon-hero);
  block-size: var(--gs-size-icon-hero);
}

.gs-identity[data-gs-size='large'] .gs-identity__name {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* -- you ------------------------------------------------------------------- */
/* Colour and weight together, never colour alone: the player's own row has to
   be findable by someone who cannot tell the two colours apart, and the
   accessible name carries the word as well. */
.gs-identity[data-gs-you='true'] .gs-identity__name {
  color: var(--gs-color-player);
  font-weight: var(--gs-type-action-font-weight);
}

/* -- signed out ------------------------------------------------------------ */
/* Quieter than a named player, and still fully legible: this is a real state a
   host renders on purpose, not a broken one. */
.gs-identity[data-gs-anonymous='true'] .gs-identity__name {
  color: var(--gs-color-ink-secondary);
}

/* -- presence -------------------------------------------------------------- */
/* On the avatar's bottom-right corner, overlapping the ring by the ring's own
   width, as drawn: a dot ringed in the edge colour so it reads against any
   picture. The colour transition survives reduced motion on purpose. */
.gs-identity__presence {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);
  /* The element that declares emphasis carries a transition of its own: the
     word's colour, beside the dot's fill below. The feel stage checks that an
     emphasis element has something to keep under reduced motion. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-identity__avatar .gs-identity__presence {
  position: absolute;
  right: calc(-1 * var(--gs-stroke-ui));
  bottom: calc(-1 * var(--gs-stroke-ui));
}

.gs-identity__presence-dot {
  display: block;
  box-sizing: border-box;
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  background: var(--gs-color-muted);
  transition: background var(--gs-motion-emphasis) ease-out,
              border-color var(--gs-motion-emphasis) ease-out;
}

.gs-identity[data-gs-presence='online'] .gs-identity__presence-dot {
  background: var(--gs-color-positive);
}

.gs-identity[data-gs-presence='away'] .gs-identity__presence-dot {
  background: var(--gs-color-warning);
}

/* Hollow, not just grey. Filled against ring is a difference in shape, so
   online and offline stay distinguishable without colour vision. */
.gs-identity[data-gs-presence='offline'] .gs-identity__presence-dot {
  background: none;
  border-color: var(--gs-color-muted);
}

/* -- the row (specimen 3a) ------------------------------------------------- */
/* A boxed line: the avatar at the medium control size, the name and its small
   print, ringed at the UI stroke in the side's colour, on a shelf. The height
   is the large action height; the drawing draws 64 and arcade's step is 68,
   a token request on the twin pair. */
.gs-identity[data-gs-presentation='row'] {
  display: flex;
  box-sizing: border-box;
  inline-size: 100%;
  block-size: var(--gs-size-action-large);
  padding: 0 var(--gs-space-inset) 0 var(--gs-space-2);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-raised);
}

.gs-identity[data-gs-presentation='row'][data-gs-side='player'] {
  border-color: var(--gs-color-player-solid);
}

.gs-identity[data-gs-presentation='row'][data-gs-side='opponent'] {
  border-color: var(--gs-color-opponent-solid);
}

.gs-identity[data-gs-presentation='row'] .gs-identity__avatar {
  inline-size: var(--gs-size-control-medium);
  block-size: var(--gs-size-control-medium);
}

.gs-identity[data-gs-presentation='row'] .gs-identity__symbol {
  font-size: var(--gs-size-icon-utility);
}

/* The name in the row is the body face at the action weight: bold on both
   sides of the row, and in the player's colour only for `you`. The drawing
   sets it at 15px/800, a size the type scale has no step for. */
.gs-identity[data-gs-presentation='row'] .gs-identity__text {
  gap: 0;
}

.gs-identity[data-gs-presentation='row'] .gs-identity__name {
  font-weight: var(--gs-type-action-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* In the row the ring carries `you`, in the player colour, and the word stays
   ink, as drawn: the ring, the weight and the word in the accessible name are
   three signals already. */
.gs-identity[data-gs-presentation='row'][data-gs-you='true'] .gs-identity__name {
  color: var(--gs-color-ink);
}

/* The small print: presence word, then whatever the host adds, at the label
   size in capitals, as drawn. */
.gs-identity[data-gs-presentation='row'] .gs-identity__detail {
  margin-top: var(--gs-space-1);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

.gs-identity[data-gs-presentation='row'] .gs-identity__presence-dot {
  inline-size: var(--gs-space-2);
  block-size: var(--gs-space-2);
  border: 0;
}
